{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-MdEJ7g/src/address.js","content":"// Address parsing and formatting helpers.

const ADDR_RE = /^([A-Za-z]{1,2})(\d{1,3})$/

/**
 * Parse an address-shaped word (already known to consist of letters then
 * digits, case irrelevant). Returns null if the shape itself is not even
 * "letters then digits" (should not normally happen for tokens produced by
 * our tokenizer, which only ever hands us that shape), otherwise returns
 * { col, row, text, valid } where col/row are 1-based numbers and `valid`
 * tells whether the address is inside the addressable range.
 */
export function parseAddressWord(word) {
  const m = ADDR_RE.exec(word)
  if (!m) return { col: null, row: null, text: word.toUpperCase(), valid: false }
  const letters = m[1].toUpperCase()
  const digits = m[2]
  let col = 0
  for (const ch of letters) {
    col = col * 26 + (ch.charCodeAt(0) - 64)
  }
  const row = parseInt(digits, 10)
  const valid = row >= 1
  return { col, row, text: letters + digits, valid }
}

export function colToLetters(col) {
  let n = col
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

export function addrKey(col, row) {
  return col + ':' + row
}

export function addrText(col, row) {
  return colToLetters(col) + String(row)
}

export function compareAddr(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

