{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-MdEJ7g/src/parser.js","content":"// Tokenizer and recursive-descent parser for formula bodies.
import { parseAddressWord } from './address.js'

class ParseError extends Error {}

function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (src[j] === '.' && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUMBER', text: src.slice(i, j), value: Number(src.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i
      while (j < n && /[A-Za-z]/.test(src[j])) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'IDENT', text: src.slice(i, j) })
      i = j
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: 'OP', text: two })
      i += 2
      continue
    }
    if ('^*/+-=<>(),: '.includes(ch) && '^*/+-=<>(),:'.includes(ch)) {
      tokens.push({ type: 'OP', text: ch })
      i++
      continue
    }
    // Unrecognized character.
    throw new ParseError('lex')
  }
  tokens.push({ type: 'EOF', text: '' })
  return tokens
}

const FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expectOp(text) {
    const t = this.peek()
    if (t.type === 'OP' && t.text === text) {
      this.pos++
      return
    }
    throw new ParseError('expected ' + text)
  }

  isOp(text) {
    const t = this.peek()
    return t.type === 'OP' && t.text === text
  }

  parseProgram() {
    const expr = this.parseComparison()
    if (this.peek().type !== 'EOF') throw new ParseError('trailing tokens')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().text)) {
      const op = this.next().text
      const right = this.parseAdditive()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOp('+') || this.isOp('-')) {
      const op = this.next().text
      const right = this.parseMultiplicative()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOp('*') || this.isOp('/')) {
      const op = this.next().text
      const right = this.parsePower()
      left = { type: 'BinOp', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.isOp('^')) {
      this.next()
      const right = this.parsePower()
      return { type: 'BinOp', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.isOp('-') || this.isOp('+')) {
      const op = this.next().text
      const operand = this.parseUnary()
      return { type: 'Unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'Num', value: t.value }
    }
    if (t.type === 'OP' && t.text === '(') {
      this.next()
      const inner = this.parseComparison()
      this.expectOp(')')
      return inner
    }
    if (t.type === 'IDENT') {
      this.next()
      const upper = t.text.toUpperCase()
      if (this.isOp('(')) {
        // function call
        this.next()
        const args = []
        if (!this.isOp(')')) {
          args.push(this.parseComparison())
          while (this.isOp(',')) {
            this.next()
            args.push(this.parseComparison())
          }
        }
        this.expectOp(')')
        return { type: 'Call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      // address, possibly the start of a range
      const info = parseAddressWord(t.text)
      const addrA = { type: 'Addr', col: info.col, row: info.row, valid: info.valid, text: info.text }
      if (this.isOp(':')) {
        this.next()
        const t2 = this.peek()
        if (t2.type !== 'IDENT') throw new ParseError('expected address after :')
        this.next()
        const info2 = parseAddressWord(t2.text)
        const addrB = { type: 'Addr', col: info2.col, row: info2.row, valid: info2.valid, text: info2.text }
        return { type: 'Range', from: addrA, to: addrB }
      }
      return addrA
    }
    throw new ParseError('unexpected token')
  }
}

/**
 * Parse a formula body (the part after the leading `=`). Returns the AST on
 * success, or null if the grammar does not accept the text.
 */
export function parseFormula(src) {
  try {
    const tokens = tokenize(src)
    const parser = new Parser(tokens)
    return parser.parseProgram()
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}

export { FUNCS }
"}

