export function roundSig10(x) {
  if (x === 0) return 0
  const rounded = Number(x.toPrecision(10))
  return rounded
}

export function formatValue(v) {
  switch (v.kind) {
    case 'number':
      return roundSig10(v.value).toString()
    case 'text':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    default:
      throw new Error('unknown value kind ' + v.kind)
  }
}
