const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGG_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export function errorValue(token) {
  return { kind: 'error', value: token }
}

export function numberValue(x) {
  if (!Number.isFinite(x)) return errorValue('#DIV/0!')
  return { kind: 'number', value: x }
}

export function boolValue(b) {
  return { kind: 'bool', value: b }
}

export function textValue(s) {
  return { kind: 'text', value: s }
}

function toNumber(v) {
  if (v.kind === 'number') return v
  if (v.kind === 'bool') return numberValue(v.value ? 1 : 0)
  if (v.kind === 'text') return errorValue('#VALUE!')
  return v // error, unchanged
}

function rank(v) {
  if (v.kind === 'number') return 0
  if (v.kind === 'text') return 1
  return 2 // bool
}

function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 0) return a.value - b.value
  if (ra === 1) return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av - bv
}

function expandRange(rangeNode) {
  const { from, to } = rangeNode
  if (!from.valid || !to.valid) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const cells = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      cells.push({ col, row })
    }
  }
  return cells
}

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet // Map key -> record
    this.memo = new Map()
    this.visiting = new Set()
  }

  evalCell(col, row) {
    const key = col + ':' + row
    if (this.memo.has(key)) return this.memo.get(key)
    const record = this.sheet.get(key)
    if (!record) {
      const v = numberValue(0)
      this.memo.set(key, v)
      return v
    }
    if (this.visiting.has(key)) {
      return errorValue('#CYCLE!')
    }
    let result
    if (record.kind === 'literal') {
      result = record.literalValue
      this.memo.set(key, result)
      return result
    }
    // formula
    if (record.ast === null) {
      result = errorValue('#ERR!')
      this.memo.set(key, result)
      return result
    }
    this.visiting.add(key)
    result = this.evalNode(record.ast)
    this.visiting.delete(key)
    this.memo.set(key, result)
    return result
  }

  evalNode(node) {
    switch (node.type) {
      case 'Num':
        return numberValue(node.value)
      case 'Bool':
        return boolValue(node.value)
      case 'Addr':
        if (!node.valid) return errorValue('#REF!')
        return this.evalCell(node.col, node.row)
      case 'Range':
        return errorValue('#ERR!')
      case 'Unary':
        return this.evalUnary(node)
      case 'BinOp':
        return this.evalBinOp(node)
      case 'Call':
        return this.evalCall(node)
      default:
        throw new Error('unknown node type ' + node.type)
    }
  }

  evalUnary(node) {
    const v = this.evalNode(node.operand)
    if (v.kind === 'error') return v
    const n = toNumber(v)
    if (n.kind === 'error') return n
    const result = node.op === '-' ? -n.value : n.value
    return numberValue(result)
  }

