        result = ln.value - rn.value
        break
      case '*':
        result = ln.value * rn.value
        break
      case '/':
        if (rn.value === 0) return errorValue('#DIV/0!')
        result = ln.value / rn.value
        break
      case '^':
        result = Math.pow(ln.value, rn.value)
        break
      default:
        throw new Error('unknown op ' + op)
    }
    return numberValue(result)
  }

