    const { name, args } = node
    if (name === 'IF') {
      if (args.length !== 3) return errorValue('#ERR!')
      const cond = this.evalNode(args[0])
      if (cond.kind === 'error') return cond
      let truthy
      if (cond.kind === 'bool') truthy = cond.value
      else if (cond.kind === 'number') truthy = cond.value !== 0
      else return errorValue('#VALUE!')
      return truthy ? this.evalNode(args[1]) : this.evalNode(args[2])
    }
    if (name === 'ABS') {
      if (args.length !== 1) return errorValue('#ERR!')
      const v = this.evalNode(args[0])
      if (v.kind === 'error') return v
      const n = toNumber(v)
      if (n.kind === 'error') return n
      return numberValue(Math.abs(n.value))
    }
    if (AGG_FUNCS.has(name)) {
      if (args.length < 1) return errorValue('#ERR!')
