        } else {
          items.push(this.evalNode(a))
        }
      }
      for (const it of items) {
        if (it.kind === 'error') return it
      }
      if (name === 'COUNT') {
        const cnt = items.filter((it) => it.kind === 'number').length
        return numberValue(cnt)
      }
      const nums = []
      for (const it of items) {
        const n = toNumber(it)
        if (n.kind === 'error') return n
        nums.push(n.value)
      }
      if (name === 'SUM') return numberValue(nums.reduce((a, b) => a + b, 0))
      if (name === 'MIN') return numberValue(Math.min(...nums))
      if (name === 'MAX') return numberValue(Math.max(...nums))
      if (name === 'AVG') return numberValue(nums.reduce((a, b) => a + b, 0) / nums.length)
    }
    return errorValue('#NAME?')
  }
}
