import { parseAddressWord, addrKey } from './address.js'
import { parseFormula } from './parser.js'
import { numberValue, textValue, errorValue } from './eval.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?\d+(\.\d+)?$/

function parseLiteral(content) {
  if (content === '') return numberValue(0)
  if (ERROR_TOKENS.has(content)) return errorValue(content)
  if (NUMBER_RE.test(content)) return numberValue(Number(content))
  return textValue(content)
}

function splitLine(trimmed) {
  let idx = -1
  for (let i = 0; i < trimmed.length; i++) {
    if (trimmed[i] === ' ' || trimmed[i] === '\t') {
      idx = i
      break
    }
  }
  if (idx === -1) return { address: trimmed, content: '' }
  const address = trimmed.slice(0, idx)
  let j = idx
  while (j < trimmed.length && (trimmed[j] === ' ' || trimmed[j] === '\t')) j++
  const content = trimmed.slice(j)
  return { address, content }
}

/**
 * Parse the sheet text into a Map keyed by "col:row" to cell records:
 * { col, row, kind: 'literal', literalValue } or
 * { col, row, kind: 'formula', ast } (ast may be null if the grammar
 * rejected the formula body).
 *
 * Throws SheetError on invalid address / duplicate declaration.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    const trimmed = line.slice(j)
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const { address, content } = splitLine(trimmed)
    const info = parseAddressWord(address)
    if (!info.valid) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${info.text}`)
    }
    const key = addrKey(info.col, info.row)
    if (sheet.has(key)) {
      throw new SheetError(`line ${lineNo}: cell ${info.text} is declared twice`)
    }

    let record
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      record = { col: info.col, row: info.row, kind: 'formula', ast }
    } else {
      record = { col: info.col, row: info.row, kind: 'literal', literalValue: parseLiteral(content) }
    }
    sheet.set(key, record)
  }
  return sheet
}
"}

