{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-MdEJ7g/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './eval.js'
import { collectDeps } from './deps.js'
import { compareAddr, addrText } from './address.js'
import { formatValue } from './values.js'

function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }

  let input
  try {
    input = fs.readFileSync(0, 'utf8')
  } catch (e) {
    input = ''
  }

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const records = [...sheet.values()].sort((a, b) => compareAddr(a, b))

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet)
    for (const rec of records) {
      const value = evaluator.evalCell(rec.col, rec.row)
      lines.push(`${addrText(rec.col, rec.row)}=${formatValue(value)}`)
    }
  } else {
    for (const rec of records) {
      const out = new Set()
      if (rec.kind === 'formula' && rec.ast) {
        collectDeps(rec.ast, out)
      }
      const cells = [...out]
        .map((key) => {
          const [col, row] = key.split(':').map(Number)
          return { col, row }
        })
        .sort(compareAddr)
        .map((c) => addrText(c.col, c.row))
      lines.push(`${addrText(rec.col, rec.row)}:` + cells.map((c) => ' ' + c).join(''))
    }
  }

  process.stdout.write(lines.map((l) => l + '\n').join(''))
  process.exit(0)
}

main()
"}

